import{a as e,i as t,r as n,t as r}from"./app-DUb33vxN.js";var i=JSON.parse(`{"path":"/%E7%AC%AC18%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E7%BB%A9%E6%95%88%E5%9F%9F/18.1%20%E7%BB%A9%E6%95%88%E5%9F%9F%E6%A6%82%E8%BF%B0.html","title":"18.1 绩效域概述","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第18章 项目绩效域/18.1 绩效域概述.md"}`),a={name:`18.1 绩效域概述.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_18-1-绩效域概述" tabindex="-1"><a class="header-anchor" href="#_18-1-绩效域概述"><span>18.1 绩效域概述</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>绩效域是指项目管理中相互关联的活动和实践领域，用于衡量和管理项目绩效，确保项目目标的实现。</p><h2 id="绩效域的概念" tabindex="-1"><a class="header-anchor" href="#绩效域的概念"><span>绩效域的概念</span></a></h2><h3 id="_1-整体性" tabindex="-1"><a class="header-anchor" href="#_1-整体性"><span>1. 整体性</span></a></h3><ul><li>绩效域之间相互关联</li><li>共同构成项目管理的整体框架</li></ul><h3 id="_2-动态性" tabindex="-1"><a class="header-anchor" href="#_2-动态性"><span>2. 动态性</span></a></h3><ul><li>绩效域随项目进展变化</li><li>需要持续监控和调整</li></ul><h3 id="_3-目标导向" tabindex="-1"><a class="header-anchor" href="#_3-目标导向"><span>3. 目标导向</span></a></h3><ul><li>每个绩效域都有明确的目标</li><li>服务于项目整体目标</li></ul><h2 id="绩效域的分类" tabindex="-1"><a class="header-anchor" href="#绩效域的分类"><span>绩效域的分类</span></a></h2><h3 id="_1-交付绩效域" tabindex="-1"><a class="header-anchor" href="#_1-交付绩效域"><span>1. 交付绩效域</span></a></h3><ul><li><strong>核心</strong>：确保项目交付物符合要求</li><li><strong>内容</strong>：范围管理、质量保证、可交付成果管理</li></ul><h3 id="_2-相关方绩效域" tabindex="-1"><a class="header-anchor" href="#_2-相关方绩效域"><span>2. 相关方绩效域</span></a></h3><ul><li><strong>核心</strong>：管理项目相关方</li><li><strong>内容</strong>：相关方识别、参与、沟通</li></ul><h3 id="_3-变更绩效域" tabindex="-1"><a class="header-anchor" href="#_3-变更绩效域"><span>3. 变更绩效域</span></a></h3><ul><li><strong>核心</strong>：管理项目变更</li><li><strong>内容</strong>：变更识别、评估、控制</li></ul><h3 id="_4-规划绩效域" tabindex="-1"><a class="header-anchor" href="#_4-规划绩效域"><span>4. 规划绩效域</span></a></h3><ul><li><strong>核心</strong>：制定和维护项目计划</li><li><strong>内容</strong>：范围规划、进度规划、成本规划</li></ul><h3 id="_5-风险绩效域" tabindex="-1"><a class="header-anchor" href="#_5-风险绩效域"><span>5. 风险绩效域</span></a></h3><ul><li><strong>核心</strong>：管理项目风险</li><li><strong>内容</strong>：风险识别、分析、应对</li></ul><h2 id="绩效域的相互关系" tabindex="-1"><a class="header-anchor" href="#绩效域的相互关系"><span>绩效域的相互关系</span></a></h2><h3 id="_1-规划是基础" tabindex="-1"><a class="header-anchor" href="#_1-规划是基础"><span>1. 规划是基础</span></a></h3><ul><li>规划绩效域为其他绩效域提供指导</li><li>确保项目有序进行</li></ul><h3 id="_2-交付是核心" tabindex="-1"><a class="header-anchor" href="#_2-交付是核心"><span>2. 交付是核心</span></a></h3><ul><li>交付绩效域是项目的核心目标</li><li>其他绩效域服务于交付</li></ul><h3 id="_3-相关方是保障" tabindex="-1"><a class="header-anchor" href="#_3-相关方是保障"><span>3. 相关方是保障</span></a></h3><ul><li>相关方绩效域确保相关方支持</li><li>为项目提供资源和支持</li></ul><h3 id="_4-变更和风险是保障" tabindex="-1"><a class="header-anchor" href="#_4-变更和风险是保障"><span>4. 变更和风险是保障</span></a></h3><ul><li>变更和风险绩效域确保项目可控</li><li>应对不确定性</li></ul><h2 id="绩效域的评估" tabindex="-1"><a class="header-anchor" href="#绩效域的评估"><span>绩效域的评估</span></a></h2><h3 id="_1-绩效指标" tabindex="-1"><a class="header-anchor" href="#_1-绩效指标"><span>1. 绩效指标</span></a></h3><ul><li>每个绩效域都有关键绩效指标</li><li>用于衡量绩效</li></ul><h3 id="_2-评估方法" tabindex="-1"><a class="header-anchor" href="#_2-评估方法"><span>2. 评估方法</span></a></h3><ul><li>定期评估绩效域状态</li><li>识别改进机会</li></ul><h3 id="_3-持续改进" tabindex="-1"><a class="header-anchor" href="#_3-持续改进"><span>3. 持续改进</span></a></h3><ul><li>根据评估结果改进</li><li>提高项目绩效</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>绩效域的定义和分类</strong></li><li><strong>绩效域的相互关系</strong></li><li><strong>绩效域的评估方法</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>绩效域五领域，交付相关方变更规划风险，相互关联保成功</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：以下哪个不属于绩效域的分类？ A. 交付绩效域 B. 相关方绩效域 C. 技术绩效域 D. 风险绩效域</p><p><strong>答案</strong>：C</p><p><strong>解析</strong>：绩效域包括交付绩效域、相关方绩效域、变更绩效域、规划绩效域和风险绩效域。技术绩效域不属于标准分类。</p>`,45)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};